module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic j,
    input  logic k,
    output logic out
);

    typedef enum logic {
        OFF = 1'b0,
        ON  = 1'b1
    } state_t;

    state_t current_state, next_state;

    // State register
    always_ff @(posedge clk) begin
        if (reset) begin
            current_state <= OFF;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always_comb begin
        next_state = current_state;
        case (current_state)
            OFF: begin
                if (j) begin
                    next_state = ON;
                end
            end
            ON: begin
                if (k) begin
                    next_state = OFF;
                end
            end
        endcase
    end

    // Output logic (Moore machine: output depends only on state)
    assign out = (current_state == ON);

endmodule

