module tb_TopModule;
    logic clk;
    logic reset;
    logic j;
    logic k;
    logic out;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .j(j),
        .k(k),
        .out(out)
    );

    // Clock generation
    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        j = 0;
        k = 0;

        #12;
        reset = 0;

        // Check reset state OFF (out=0)
        #1;
        if (out !== 0) begin
            $display("SELFTEST FAIL: Reset state output is not 0 (got %b)", out);
            $finish;
        end

        // OFF -> j=0 -> OFF
        @(posedge clk);
        j = 0; k = 0;
        #2;
        if (out !== 0) begin
            $display("SELFTEST FAIL: OFF state with j=0 should stay OFF");
            $finish;
        end

        // OFF -> j=1 -> ON
        @(posedge clk);
        j = 1; k = 0;
        #2;
        if (out !== 1) begin
            $display("SELFTEST FAIL: OFF state with j=1 should transition to ON (got %b)", out);
            $finish;
        end

        // ON -> k=0 -> ON
        @(posedge clk);
        j = 0; k = 0;
        #2;
        if (out !== 1) begin
            $display("SELFTEST FAIL: ON state with k=0 should stay ON");
            $finish;
        end

        // ON -> k=1 -> OFF
        @(posedge clk);
        j = 0; k = 1;
        #2;
        if (out !== 0) begin
            $display("SELFTEST FAIL: ON state with k=1 should transition to OFF");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

